To modify your code to use a shared base class `Quantity` for `Temperature`, `Length`, and `Mass` classes, you can follow this approach:

### Step-by-step Explanation:

1. **Create a base class `Quantity`** that defines common attributes and methods for all derived classes.
2. **Inherit from `Quantity`** in each of the derived classes (`Temperature`, `Length`, `Mass`).
3. **Add specific attributes or methods** in each derived class to handle their unique behavior.

Here's an example implementation:

```python
class Quantity:
    def __init__(self, value):
        self._value = value

    def value(self):
        return self._value

    def __add__(self, other):
        if isinstance(other, Quantity):
            return Quantity(self.value() + other.value())
        return NotImplemented

    def __sub__(self, other):
        if isinstance(other, Quantity):
            return Quantity(self.value() - other.value())
        return NotImplemented

    def __mul__(self, other):
        if isinstance(other, (int, float)):
            return Quantity(self.value() * other)
        return NotImplemented

    def __truediv__(self, other):
        if isinstance(other, (int, float)):
            return Quantity(self.value() / other)
        return NotImplemented

    def __repr__(self):
        return f"{self.__class__.__name__}({self.value()})"


class Temperature(Quantity):
    def __init__(self, value, unit='Celsius'):
        super().__init__(value)
        self._unit = unit

    @property
    def unit(self):
        return self._unit

    def __repr__(self):
        return f"Temperature({self.value()}, {self.unit})"


class Length(Quantity):
    def __init__(self, value, unit='meters'):
        super().__init__(value)
        self._unit = unit

    @property
    def unit(self):
        return self._unit

    def __repr__(self):
        return f"Length({self.value()}, {self.unit})"


class Mass(Quantity):
    def __init__(self, value, unit='kilograms'):
        super().__init__(value)
        self._unit = unit

    @property
    def unit(self):
        return self._unit

    def __repr__(self):
        return f"Mass({self.value()}, {self.unit})"
```

